:root{font-synthesis:none}
/* --on-accent / --on-red: ink for anything drawn on an accent or red fill. Never hard-code #fff there:
   white on the dark themes' pastel accents reads at 2.0-2.4:1. --text-faint clears 4.5:1 on --bg-content. */
html[data-theme="frost-light"]{
