*{box-sizing:border-box;margin:0;padding:0}
body{min-height:100vh;display:grid;place-items:center;padding:24px;background:var(--bg-app);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text",system-ui,sans-serif;-webkit-font-smoothing:antialiased}
.card{width:380px;max-width:100%;background:var(--bg-window);border:1px solid var(--border-strong);border-radius:18px;box-shadow:0 30px 70px rgba(0,0,0,.5);padding:34px 30px 26px}
.brand{display:flex;flex-direction:column;align-items:center;gap:12px;margin-bottom:22px}
.mk{width:60px;height:60px;border-radius:15px;box-shadow:0 10px 24px rgba(0,0,0,.35);overflow:hidden}
.mk svg{width:100%;height:100%;display:block}
h1{font-size:21px;font-weight:700}.sub{font-size:13px;color:var(--text-dim);margin-top:-6px}
label{display:block;font-size:12px;font-weight:600;color:var(--text-dim);margin:0 0 6px}
.fld{margin-bottom:14px}
input{width:100%;height:42px;background:var(--bg-input);border:1px solid var(--border);border-radius:10px;padding:0 12px;font-size:14px;color:var(--text)}
input:focus{border-color:var(--accent)}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
button{width:100%;height:42px;border:0;border-radius:10px;background:var(--accent);color:var(--on-accent);font-size:14px;font-weight:600;cursor:pointer;margin-top:6px}
button:hover{background:var(--accent-press)}
button:disabled{opacity:.6;cursor:progress}button:disabled:hover{background:var(--accent)}
.err{background:var(--red-soft);color:var(--red);font-size:12.5px;border-radius:9px;padding:9px 11px;margin-bottom:14px;text-align:center}
.foot{margin-top:20px;padding-top:16px;border-top:1px solid var(--border);text-align:center;font-size:11.5px;color:var(--text-faint);line-height:1.6}
.warn{color:var(--orange)}
.pw{position:relative}
.pw input{padding-right:46px}
.pw input::-ms-reveal{display:none}
button.eye{position:absolute;top:4px;right:4px;width:34px;height:34px;margin:0;padding:0;display:grid;place-items:center;border-radius:8px;background:transparent;color:var(--text-dim)}
button.eye:hover{background:var(--bg-input);color:var(--text)}
.eye svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.eye .i-hide,.eye[aria-pressed="true"] .i-show{display:none}
.eye[aria-pressed="true"] .i-hide{display:block}
.caps{margin-top:6px;font-size:12px;color:var(--orange)}
.secure{color:var(--green)}
[hidden]{display:none!important}

"""#

    public static let serviceWorker = #"""
// Goel° portal service worker. It caches nothing: every page and API call goes to the server,
// which holds the session. It exists so an installed portal opens to a clear "server
// unreachable" screen instead of the browser's own error page when the daemon is down.

const OFFLINE_HTML = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="refresh" content="10">
<title>Goel° — Reconnecting</title>
<style>
  :root { color-scheme: light dark; }
  body { margin: 0; font: 15px/1.5 -apple-system, system-ui, sans-serif; background: #15171d; color: #eef1f7;
         display: grid; min-height: 100vh; place-items: center; }
  @media (prefers-color-scheme: light) { body { background: #f4f6fa; color: #1a1c22; } }
  .bar { position: fixed; top: 0; left: 0; right: 0; padding: 8px 16px; background: rgba(251,191,107,.18);
         color: #fbbf6b; font-weight: 600; text-align: center; }
  @media (prefers-color-scheme: light) { .bar { color: #a85800; } }
  main { max-width: 360px; padding: 24px; text-align: center; }
  h1 { font-size: 20px; margin: 0 0 8px; }
  p { margin: 0 0 16px; opacity: .8; }
  a { color: #8aa2ff; }
</style></head><body>
<div class="bar" role="status">Reconnecting to Goel°…</div>
<main><h1>Can’t reach the Goel° server</h1>
<p>Check that the daemon is running and this device is on the same network. This page retries every 10 seconds.</p>
<a href="/">Try again now</a></main>
</body></html>`

self.addEventListener('install', () => self.skipWaiting())
self.addEventListener('activate', (event) => event.waitUntil(self.clients.claim()))

self.addEventListener('fetch', (event) => {
  // Only whole-page loads: the event stream, streams and API calls must reach the server untouched.
  if (event.request.mode !== 'navigate') return
  event.respondWith(
    fetch(event.request).catch(
      () =>
        new Response(OFFLINE_HTML, {
          status: 503,
          headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' },
        }),
    ),
  )
})

